import{z as o,x as s,o as B,c as d,q as l,j as i,D as E,d as t,s as A,S as r,b as e}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"有限注意力与公告漂移","description":"","frontmatter":{"title":"有限注意力与公告漂移","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/limited-attention-pead.md","filePath":"econ/limited-attention-pead.md","lastUpdated":1791413859000}'),p={name:"econ/limited-attention-pead.md"};function m(D,a,h,c,C,f){const n=s("Mermaid");return B(),d("div",null,[a[2]||(a[2]=l('<h1 id="有限注意力与公告漂移" tabindex="-1">有限注意力与公告漂移 <a class="header-anchor" href="#有限注意力与公告漂移" aria-label="Permalink to &quot;有限注意力与公告漂移&quot;">​</a></h1><div class="epigraph"><p>盈余已经公开，不等于已经进入每个人的信息集；没被注意到的公告，价格会在随后的日子里慢慢走完该走的路。</p><footer>—— Bernard and Thomas 的盈余公告后漂移；DellaVigna and Pollet, JF 2009；Hirshleifer, Lim and Teoh 的注意力约束</footer></div><p><a href="/econ/herding-cascades">上一课</a>让人看见行动却扔掉信号。本课缺口是看见本身：有限注意力使公开信息延迟进入价格，PEAD 成为半强式的候选拒绝。本课程最后一课；下一课程从<a href="/econ/grossman-stiglitz">Grossman–Stiglitz</a>起，贸易课程其后从<a href="/econ/ricardian-comparative-advantage">李嘉图</a>起。不重写 BHW 的级联阈值，不进入限价簿。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Bernard 与 Thomas 记录：盈余未预期在公告后仍预测漂移，符号与标准化意外一致。半强式 <a href="/econ/emh">EMH</a> 要求公开盈余立刻被写入；联合假说仍在，但注意力给出具体机制。Hirshleifer、Lim 与 Teoh：同一天公告太多，每个公告的即时反应变弱、漂移变强。DellaVigna 与 Pollet（2009）：周五公告即时反应更弱、漂移更强——投资者注意力在周五下降。Barber 与 Odean（2008）：散户买注意力抓取的股票（新闻、极端收益、异常放量），卖的一侧不受同样驱动。</p><p>缺口是把<a href="/econ/salience-attention">显著性</a>接到公开信息的加总，而不是再写 BSV 的体制切换——二者可叠加：看见了仍可更新不足。</p><p><span class="marginnote">术语翻译：PEAD（盈余公告后漂移）就是「好消息的股票在公告后几周还继续慢慢涨、坏消息的继续慢慢跌」——价格没有一次走完，而是分好几天才消化完这条新闻。</span></p><p><span class="marginnote">PEAD 不是微观结构买卖价差能单独解释的量级。本课对象是信息集何时真正变成 Fama 意义上的「可用」。簿的几何仍归量化栏。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>事件研究按注意力代理分组：周五、同一日公告数量、媒体覆盖、散户搜索。预测：低注意力组即时 \\(\\beta\\) 小、随后漂移大。对照 Hong–Stein：HS 是信息在人群中扩散；本课强调日历与竞争性刺激对同一公开文本的忽略。套利限制解释为何漂移不被即时吃掉：SV 的资本、卖空成本、噪声交易者风险都可后台待命。</p><p><span class="marginnote">数字实例：周五下午发的盈余公告，不少人已经心不在焉，当日即时涨幅常小于工作日发的同等信息公告；随后几十个交易日里，「没走完的行情」继续兑现。DellaVigna–Pollet 正是用周五与周三对照，把「注意力」从嘴上争论变成可测的分组变量。</span></p>',11)),(B(),i(r,null,{default:E(()=>[A(n,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20PUB%5B%22%E5%85%AC%E5%BC%80%E7%9B%88%E4%BD%99%22%5D%20--%3E%20ATT%5B%22%E6%9C%89%E9%99%90%E6%B3%A8%E6%84%8F%E5%8A%9B%3A%20%E4%B8%80%E9%83%A8%E5%88%86%E4%BA%BA%E6%B2%A1%E7%9C%8B%E8%A7%81%22%5D%0A%20%20ATT%20--%3E%20UNDER%5B%22%E5%8D%B3%E6%97%B6%E5%8F%8D%E5%BA%94%E4%B8%8D%E8%B6%B3%22%5D%0A%20%20UNDER%20--%3E%20PEAD%5B%22%E9%9A%8F%E5%90%8E%E6%BC%82%E7%A7%BB%22%5D%0A%20%20PEAD%20--%3E%20LTA%5B%22%E5%A5%97%E5%88%A9%E9%99%90%E5%88%B6%3A%20%E6%BC%82%E7%A7%BB%E5%8F%AF%E8%A2%AB%E4%BA%A4%E6%98%93%E4%BD%86%E6%9C%AA%E6%B6%88%E5%A4%B1%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"主干在限价簿交接处停；本课仍是补层的价格理论，用的是公告后的收益路径，不是档位与队列。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"机制是信息集的实际到达。Fama 的「可用」在操作上被注意力改写：文本在新闻稿上，不在决策者的 \\(v\\) 里。价格由注意到的人移动一块，未注意到的人稍后读到再移动一块——看起来像滞后，其实是分批到达，近乎 HS 的日历版。概率加权与前景理论可以再扭曲已注意到的人的反应；本课主效应是「有没有看见」。",-1)),(B(),i(r,null,{default:E(()=>[A(n,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20ANN%5B%22%E5%90%8C%E4%B8%80%E6%9D%A1%E7%9B%88%E4%BD%99%E5%85%AC%E5%91%8A%22%5D%20--%3E%20HI%5B%22%E9%AB%98%E6%B3%A8%E6%84%8F%E5%8A%9B%EF%BC%9A%E5%B7%A5%E4%BD%9C%E6%97%A5%E3%80%81%E7%8B%AC%E5%AE%B6%E3%80%81%E9%AB%98%E6%90%9C%E7%B4%A2%22%5D%0A%20%20ANN%20--%3E%20LO%5B%22%E4%BD%8E%E6%B3%A8%E6%84%8F%E5%8A%9B%EF%BC%9A%E5%91%A8%E4%BA%94%E3%80%81%E6%8B%A5%E6%8C%A4%E6%97%A5%E3%80%81%E5%B0%91%E8%A6%86%E7%9B%96%22%5D%0A%20%20HI%20--%3E%20Q1%5B%22%E5%A4%9A%E6%95%B0%E4%BA%BA%E7%AB%8B%E5%88%BB%E6%9B%B4%E6%96%B0%EF%BC%8C%E4%BB%B7%E6%A0%BC%E4%B8%80%E6%AD%A5%E5%88%B0%E4%BD%8D%22%5D%0A%20%20LO%20--%3E%20Q2%5B%22%E5%8F%AA%E6%9C%89%E5%B0%91%E6%95%B0%E4%BA%BA%E7%9C%8B%E5%88%B0%EF%BC%8C%E5%8D%B3%E6%97%B6%E5%8F%8D%E5%BA%94%E5%B0%8F%22%5D%0A%20%20Q2%20--%3E%20D1%5B%22%E5%85%B6%E4%BD%99%E4%BA%BA%E5%88%86%E6%89%B9%E8%AF%BB%E5%88%B0%EF%BC%8C%E9%9A%8F%E5%90%8E%E5%87%A0%E5%A4%A9%E4%BB%B7%E6%A0%BC%E6%BC%82%E7%A7%BB%22%5D%0A%20%20Q1%20--%3E%20N1%5B%22%E5%9F%BA%E6%9C%AC%E6%B2%A1%E6%9C%89%E5%90%8E%E7%BB%AD%E6%BC%82%E7%A7%BB%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=l('<p>家庭金融闭环：素养与默认决定谁参与；参与者仍受注意力约束，于是公开信息对家庭组合的写入也是慢的。行为单元的零件在此全部接到一条可交易的预测：低注意力公告后的漂移。</p><p><span class="marginnote">直觉类比：把市场想成一群每天只刷一两次手机的人。新闻发了，但每个时段只有一部分人刷到；价格是「看到的人」出的——人分批看到，价格就分批走完。这就是「公开」与「进入信息集」的区别。</span></p><p>Fama 半强式的「可用」在操作上被注意力改写。周五、拥挤日把同一篇新闻稿变成更少人的 \\(\\mathcal{F}_t\\)。即时反应弱、随后漂移，是分批到达，近乎 Hong–Stein 的日历版；BSV 的保守可以叠加在已看见的人身上。套利限制解释为何 alpha 不被立刻吃掉。本课程补层从跨期偏好走到此处，仍不重写簿：收益路径是事件，档位是协议。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>风险补偿（公告后风险变）与会计应计异象会污染 PEAD。注意力代理（周五）可能相关于发布公司的类型。本课不估计年化 alpha，不把策略写成可执行清单。量化栏若做事件研究，用本课当理论对照，用簿当成交定义。</p><p>后课不在本课程。补层到此：跨期偏好 → 行为零件 → 市场加总。仍不重写簿。</p><p>公开不等于进入每个人的 \\(\\mathcal{F}_t\\)。周五与拥挤日即时弱、漂移强。</p><p>补层从跨期偏好走到此处，收益路径仍是事件不是档位。套利限制解释 alpha 为何还在。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>有限注意力让公开公告延迟进入价格，PEAD 是半强式的机制候选。</li><li>周五、拥挤的公告日，即时弱、漂移强。</li><li>与 HS/BSV 可叠加；存活仍靠套利限制。</li><li>与 HS 的日历版近亲，与 BSV 的保守可叠加。</li><li>本课程后课不在此；不重写簿。</li><li>出处：Bernard and Thomas；DellaVigna and Pollet, <em>JF</em> 2009；Hirshleifer, Lim and Teoh；Barber and Odean, <em>RFS</em> 2008。</li></ul>',10))])}const _=o(p,[["render",m]]);export{F as __pageData,_ as default};
